/**
 *  A dev theme (#140) was recompiled after its folder changed: re-apply it
 *  when it is the active one. `error` when it no longer compiles.
 */
export type ThemeReloaded_Deserialize = {
	theme: string,
	error?: string | null,
};

/**
 *  A dev theme (#140) was recompiled after its folder changed: re-apply it
 *  when it is the active one. `error` when it no longer compiles.
 */
export type ThemeReloaded_Serialize = {
	theme: string,
	error: string | null,
};

/**  Where a theme was found. */
export type ThemeSource = "builtin" | "user" | "plugin" | 
/**  A folder loaded in place in dev mode, watched for changes. */
"dev";

